        parent::__construct($uid);
        $this->_target = MessageTargetVO::from($target);
        $this->_tenant = null === $tenant ? MessageTenantVO::empty() : MessageTenantVO::from($tenant);
        $this->_urgent = MessageUrgentVO::from($urgent);
        $this->_content = MessageContentVO::from($content);
        $this->_retries = MessageRetriesVO::from($retries);
        $this->_createdAt = MessageCreatedAtVO::from($createdAt);
        $this->_sendAt = null === $sendAt ? MessageSendAtVO::empty() : MessageSendAtVO::from($sendAt);
        $this->_lockAt = null === $lockAt ? MessageLockAtVO::empty() : MessageLockAtVO::from($lockAt);
        $this->_version = null === $version ? MessageVersionVO::empty() : MessageVersionVO::from($version);
    }
    public function replace(MessageAttributes $values): Message
    {
        $value = clone $this;
        $value->_target = $values->getTargetOrDefault($this->_target);
        $value->_tenant = $values->getTenantOrDefault($this->_tenant);
        $value->_urgent = $values->getUrgentOrDefault($this->_urgent);
        $value->_content = $values->getContentOrDefault($this->_content);
        $value->_retries = $values->getRetriesOrDefault($this->_retries);
        $value->_createdAt = $values->getCreatedAtOrDefault($this->_createdAt);
        $value->_sendAt = $values->getSendAtOrDefault($this->_sendAt);
        $value->_lockAt = $values->getLockAtOrDefault($this->_lockAt);
        $value->_version = $values->getVersionOrDefault($this->_version);
        return $value;
    }
    public static function calculatedFields(): array
    {
        return [ 'createdAt', 'sendAt', 'lockAt'];
    }
    public static function create(MessageAttributes $values): Message
    {
        $calculated = clone $values;
        $calculated->createdAt(CreatedAtCalculator::calculateCreatedAt());
        $calculated->sendAt(SendAtCalculator::calculateSendAt());
        $calculated->lockAt(LockAtCalculator::calculateLockAt());
        $value = $calculated->build();
        $value->recordedEvents[] = new MessageCreateEvent($value);
        return $value;
    }
    public function update(MessageAttributes $values): Message
    {
        $calculated = clone $values;
        $calculated->createdAt(CreatedAtCalculator::calculateCreatedAt($this));
        $calculated->sendAt(SendAtCalculator::calculateSendAt($this));
        $calculated->lockAt(LockAtCalculator::calculateLockAt($this));
        $value = $this->replace($calculated);
        $value->recordedEvents[] = new MessageUpdateEvent($value, $this);
        return $value;
    }
    public function delete(): Message
    {
        $value = clone $this;
        $value->recordedEvents[] = new MessageDeleteEvent($value);
        return $value;
    }
    public function asPublicJson(): array
    {
        $data = [];
        $data['uid'] = $this->uid();
        $data['target'] = $this->getTarget();
        $tenant = $this->getTenant();
        if (null !== $tenant) {
